function App() {
  return (
    <main
      style={{
        minHeight: "100vh",
        margin: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        fontFamily: "Segoe UI, system-ui, sans-serif",
        background: "#0f172a",
        color: "#e2e8f0",
      }}
    >
      <h1 style={{ fontSize: "2.5rem", fontWeight: 600, letterSpacing: "-0.02em" }}>
        Engagement Engine
      </h1>
    </main>
  );
}

export default App;
